    ];




    // Sort members by old_family_no to ensure proper family grouping
    usort($members, function ($a, $b) {
      $aFamily = $a['old_family_no'] ?? '1';
      $bFamily = $b['old_family_no'] ?? '1';
      return strcmp($aFamily, $bFamily);
    });

    // Initialize counters for member numbering
    // Start from where MemberSeeder left off
    // Get the count of members in the first seeder to continue the sequence
    $memberSeederPath = __DIR__ . '/MemberSeeder.php';
    $memberSeederContent = file_get_contents($memberSeederPath);
    preg_match_all("/'first_name'=>/", $memberSeederContent, $matches);
    $firstSeederCount = count($matches[0]);

    $memberCounter = $firstSeederCount + 1;

    // For family counter, we need to find the highest family number used in the first seeder
    // Extract all old_family_no values from first seeder to calculate max family groups
    preg_match_all("/'old_family_no'=>'([^']+)'/", $memberSeederContent, $familyMatches);
    $firstSeederFamilies = array_unique($familyMatches[1]);
    $firstSeederFamilyCount = count($firstSeederFamilies);

    $familyCounter = $firstSeederFamilyCount + 1;
    $familyGroups = [];
    $familyMemberCounters = [];

    // Process each member with proper numbering
    foreach ($members as $index => $member) {
      // Generate family_no based on old_family_no
      $oldFamilyNo = $member['old_family_no'] ?? '1';

      if (!isset($familyGroups[$oldFamilyNo])) {
        $familyGroups[$oldFamilyNo] = $familyCounter;
        $familyMemberCounters[$oldFamilyNo] = 1;
        $familyCounter++;
      }

      $familyGroup = str_pad($familyGroups[$oldFamilyNo], 3, '0', STR_PAD_LEFT);

      // Generate family_no: SAL-XXX (XXX = family group, all members in same family share same number)
      $familyNo = "SAL-{$familyGroup}";

      // Generate member_no: YYYY-SAL-MNNNNN
      $memberNo = "2025-SAL-M" . str_pad($memberCounter, 6, '0', STR_PAD_LEFT);

      // Update member data with new numbering
      $members[$index] = array_merge($member, [
        'family_no' => $familyNo,
        'member_no' => $memberNo,
        'registration_year' => '2025',
        'family_sequence' => (int) $familyGroup,
        'member_sequence' => $memberCounter,

      ]);

      $familyMemberCounters[$oldFamilyNo]++;
      $memberCounter++;
    }

    // Insert members in chunks
    $chunks = array_chunk($members, 500);
    foreach ($chunks as $chunk) {
      DB::table('members')->insert($chunk);
    }
  }
